715→              >
716→                <button
717→                  type="button"
718→                  onClick={addRow}
719→                  style={{
720→                    display: "block",
721→                    width: "100%",
722→                    background: "none",
723→                    border: "none",
724→                    cursor: "pointer",
725→                    color: "#2c6ecb",
726→                    fontSize: "13px",
727→                    fontWeight: 600,
728→                    padding: "10px 14px",
