        <div
          style={{
            display: "flex",
            gap: "4px",
            background: "#f6f6f7",
            borderRadius: "20px",
            padding: "3px",
            border: "1px solid #e1e3e5",
          }}
        >
          {data.units.available.map((unit) => (
            <button
              key={unit}
              type="button"
              onClick={() => toggleUnit(unit)}
              style={{
                padding: "3px 14px",
                borderRadius: "16px",
                border: "none",
                background:
                  data.units.default === unit ? "#2c6ecb" : "transparent",
