    chart ? (parseChartData(chart.data).recommendationEnabled ?? false) : false,
  );

  const isSaving = saveFetcher.state !== "idle";
  const isTogglingStatus = statusFetcher.state !== "idle";

  // Check for ?saved=1 on mount (after redirect from new chart creation)
  useEffect(() => {
    if (typeof window !== "undefined") {
      const url = new URL(window.location.href);
      if (url.searchParams.get("saved") === "1") {
        shopify.toast.show("Chart created successfully");
        url.searchParams.delete("saved");
        window.history.replaceState({}, "", url.toString());
      }
    }
  }, [shopify]);

  // Save feedback
  useEffect(() => {
    if (!saveFetcher.data) return;
    const data = saveFetcher.data;
    if ("ok" in data && data.ok) {
      shopify.toast.show(data.message ?? "Saved");
    } else if ("error" in data) {
      shopify.toast.show(data.error ?? "An error occurred", { isError: true });
    }
  }, [saveFetcher.data, shopify]);

  // Status toggle feedback
  useEffect(() => {
    if (!statusFetcher.data) return;
    const data = statusFetcher.data;
    if ("ok" in data && data.ok) {
      shopify.toast.show(data.message ?? "Status updated");
      if ("newStatus" in data && typeof data.newStatus === "string") {
        setStatus(data.newStatus);
      }
    } else if ("error" in data) {
      shopify.toast.show(data.error ?? "An error occurred", { isError: true });
    }
  }, [statusFetcher.data, shopify]);

  // Assignment feedback
  useEffect(() => {
    if (!assignmentFetcher.data) return;
    const data = assignmentFetcher.data;
    if ("ok" in data && data.ok) {
      shopify.toast.show(data.message ?? "Done");
      setNewAssignmentValue("");
    } else if ("error" in data) {
      shopify.toast.show(data.error ?? "An error occurred", { isError: true });
    }
  }, [assignmentFetcher.data, shopify]);

  const handleSave = () => {
    const formData = new FormData();
    formData.set("intent", "save");
    formData.set("name", name);
    formData.set("category", category);
    formData.set("status", status);
    const fullData: ChartData = {
      ...chartData,
      displaySettings: { priority, countries, selectedCountries, buttonPosition },
      recommendationEnabled,
    };
    formData.set("data", JSON.stringify(fullData));
    saveFetcher.submit(formData, { method: "post" });
  };

  const handleToggleStatus = () => {
    const formData = new FormData();
    formData.set("intent", "toggle-status");
    statusFetcher.submit(formData, { method: "post" });
  };

  const handleAddAssignment = () => {
    if (!newAssignmentValue.trim() && newAssignmentType !== "all") return;
    const formData = new FormData();
    formData.set("intent", "add-assignment");
    formData.set("assignmentType", newAssignmentType);
    formData.set(
      "assignmentValue",
      newAssignmentType === "all" ? "*" : newAssignmentValue.trim(),
    );
    assignmentFetcher.submit(formData, { method: "post" });
    setAssignments((prev) => [
      ...prev,
      {
        id: `temp-${Date.now()}`,
        assignmentType: newAssignmentType,
        assignmentValue:
          newAssignmentType === "all" ? "*" : newAssignmentValue.trim(),
      },
    ]);
  };

  const handleRemoveAssignment = (assignmentId: string) => {
    const formData = new FormData();
    formData.set("intent", "remove-assignment");
    formData.set("assignmentId", assignmentId);
    assignmentFetcher.submit(formData, { method: "post" });
    setAssignments((prev) => prev.filter((a) => a.id !== assignmentId));
  };

  const assignmentTypeLabel = (type: string) =>
    ASSIGNMENT_TYPES.find((t) => t.value === type)?.label ?? type;

  const tabs = [
    { id: "chart" as const, label: "Size Chart" },
    { id: "assignments" as const, label: `Assignments${assignments.length > 0 ? ` (${assignments.length})` : ""}` },
    { id: "position" as const, label: "Position" },
    { id: "recommendation" as const, label: "AI Recommendation" },
    { id: "settings" as const, label: "Settings" },
  ] satisfies { id: ActiveTab; label: string }[];

  return (
    <Page
      title={isNew ? "New Size Chart" : name}
      backAction={{ onAction: () => navigate("/app/size-charts") }}
      primaryAction={
        <Button
          variant="primary"
          onClick={handleSave}
          loading={isSaving}
          disabled={isSaving}
        >
          {isSaving ? "Saving..." : "Save"}
        </Button>
      }
      secondaryActions={[
        {
          content: status === "active" ? "Unpublish" : "Publish",
          onAction: handleToggleStatus,
          loading: isTogglingStatus,
          disabled: isNew || isTogglingStatus,
        },
      ]}
    >
      <Layout>
        <Layout.Section>
          <BlockStack gap="400">
            {/* ============================================================ */}
            {/* Tab navigation                                                */}
            {/* ============================================================ */}
            <div style={{ borderBottom: "1px solid #e1e3e5", paddingBottom: "1px" }}>
              <ButtonGroup variant="segmented">
                {tabs.map((tab) => (
                  <Button
                    key={tab.id}
                    pressed={activeTab === tab.id}
                    onClick={() => setActiveTab(tab.id)}
                  >
                    {tab.label}
                  </Button>
                ))}
              </ButtonGroup>
            </div>

            {/* ============================================================ */}
            {/* TAB: Size Chart                                               */}
            {/* ============================================================ */}
            {activeTab === "chart" && (
              <BlockStack gap="400">
                {/* General Settings card */}
                <Card>
                  <BlockStack gap="400">
                    <InlineStack gap="400" align="start" blockAlign="center">
                      <Text as="h2" variant="headingMd" fontWeight="bold">
                        General Settings
                      </Text>
                      <Badge tone={status === "active" ? "success" : "new"}>
                        {status === "active" ? "Published" : "Draft"}
                      </Badge>
                    </InlineStack>
                    <TextField
                      label="Chart name"
                      value={name}
                      onChange={(value) => setName(value)}
                      placeholder="e.g. Women's Tops Size Chart"
                      autoComplete="off"
                    />
                    <Select
                      label="Category"
                      value={category}
                      onChange={(value) => setCategory(value)}
                      options={CATEGORIES}
                    />
                  </BlockStack>
                </Card>

                {/* Size Table card */}
                <Card>
                  <BlockStack gap="400">
                    <BlockStack gap="200">
                      <Text as="h2" variant="headingMd" fontWeight="bold">
                        Size Table
                      </Text>
                      <Text as="p" variant="bodyMd" tone="subdued">
                        Click any cell to edit. Click a column header to rename it. Use the + buttons to add rows or columns.
                      </Text>
                    </BlockStack>
                    <TableEditor data={chartData} onChange={setChartData} />
                  </BlockStack>
                </Card>
              </BlockStack>
            )}

            {/* ============================================================ */}
            {/* TAB: Assignments                                              */}
            {/* ============================================================ */}
            {activeTab === "assignments" && (
              <BlockStack gap="400">
                {/* Current Assignments card */}
                <Card>
                  <BlockStack gap="400">
                    <BlockStack gap="200">
                      <Text as="h2" variant="headingMd" fontWeight="bold">
                        Current Assignments
                      </Text>
                      <Text as="p" variant="bodyMd" tone="subdued">
                        This chart will appear on matching product pages.
                      </Text>
                    </BlockStack>

                    {/* New chart info banner */}
                    {isNew && (
                      <Banner tone="info">
                        <Text as="p" variant="bodyMd">
                          Save the chart first to add product assignments.
                        </Text>
                      </Banner>
                    )}

                    {/* Existing assignments list */}
                    {assignments.length > 0 && (
                      <div
                        style={{
                          border: "1px solid #e3e3e3",
                          borderRadius: "8px",
                          overflow: "hidden",
                        }}
                      >
                        {assignments.map((assignment, i) => (
                          <div
                            key={assignment.id}
                            style={{
                              display: "flex",
                              alignItems: "center",
                              gap: "12px",
                              padding: "11px 14px",
                              background: i % 2 === 0 ? "#ffffff" : "#fafbfb",
                              borderBottom:
                                i < assignments.length - 1
                                  ? "1px solid #e3e3e3"
                                  : "none",
                            }}
                          >
                            <Badge tone="info">
                              {assignmentTypeLabel(assignment.assignmentType)}
                            </Badge>
                            <span
                              style={{
                                flex: 1,
                                fontSize: "13px",
                                color: "#202223",
                                fontWeight: 500,
                                fontFamily: "monospace",
                              }}
                            >
                              {assignment.assignmentValue === "*"
                                ? "All products"
                                : assignment.assignmentValue}
                            </span>
                            <Button
                              tone="critical"
                              variant="plain"
                              onClick={() => handleRemoveAssignment(assignment.id)}
                            >
                              Remove
                            </Button>
                          </div>
                        ))}
                      </div>
                    )}

                    {/* Empty state */}
                    {assignments.length === 0 && !isNew && (
                      <div
                        style={{
                          border: "1.5px dashed #c9cccf",
                          borderRadius: "8px",
                          padding: "28px 16px",
                          textAlign: "center",
                          background: "#fafbfb",
                        }}
                      >
                        <div style={{ fontSize: "28px", marginBottom: "8px", lineHeight: 1 }}>
                          &#128205;
                        </div>
                        <Text as="p" variant="bodyMd">
                          No assignments yet
                        </Text>
                        <Text as="p" variant="bodyMd" tone="subdued">
                          Add an assignment below to show this chart on product pages.
                        </Text>
                      </div>
                    )}
                  </BlockStack>
                </Card>

                {/* Add Assignment card */}
                {!isNew && (
                  <Card>
                    <BlockStack gap="400">
                      <BlockStack gap="200">
                        <Text as="h2" variant="headingMd" fontWeight="bold">
                          Add Assignment
                        </Text>
                        <Text as="p" variant="bodyMd" tone="subdued">
                          Target by product, collection, tag, or product type.
                        </Text>
                      </BlockStack>
                      <InlineStack gap="400" blockAlign="end" wrap={false}>
                        <div style={{ flex: "0 0 200px" }}>
                          <Select
                            label="Type"
                            value={newAssignmentType}
                            onChange={(value) => setNewAssignmentType(value)}
                            options={ASSIGNMENT_TYPES}
                          />
                        </div>
                        {newAssignmentType !== "all" && (
                          <div
                            style={{ flex: 1 }}
                            onKeyDown={(e: React.KeyboardEvent) => {
                              if (e.key === "Enter") {
                                e.preventDefault();
                                handleAddAssignment();
                              }
                            }}
                          >
                            <TextField
                              label="Value"
                              value={newAssignmentValue}
                              onChange={(value) => setNewAssignmentValue(value)}
                              placeholder={
                                newAssignmentType === "tag"
                                  ? "e.g. summer-sale"
                                  : newAssignmentType === "product_type"
                                    ? "e.g. T-Shirts"
                                    : newAssignmentType === "collection"
                                      ? "e.g. gid://shopify/Collection/123"
                                      : "e.g. gid://shopify/Product/123"
                              }
                              autoComplete="off"
                            />
                          </div>
                        )}
                        <Button
                          variant="primary"
                          onClick={handleAddAssignment}
                          loading={assignmentFetcher.state !== "idle"}
                        >
                          Add
                        </Button>
                      </InlineStack>
                    </BlockStack>
                  </Card>
                )}
              </BlockStack>
            )}

            {/* ============================================================ */}
            {/* TAB: Position                                                 */}
            {/* ============================================================ */}
            {activeTab === "position" && (
              <BlockStack gap="400">
                {/* Priority card */}
                <Card>
                  <BlockStack gap="400">
                    <BlockStack gap="200">
                      <Text as="h2" variant="headingMd" fontWeight="bold">
                        Display Priority
                      </Text>
                      <Text as="p" variant="bodyMd" tone="subdued">
                        When multiple charts match a product, the one with the lowest priority number is shown first.
                      </Text>
                    </BlockStack>
                    <InlineStack gap="400" blockAlign="center">
                      <div style={{ width: "120px" }}>
                        <TextField
                          label="Priority level"
                          type="number"
                          value={String(priority)}
                          onChange={(value) =>
                            setPriority(Math.max(1, Math.min(100, parseInt(value, 10) || 1)))
                          }
                          min={1}
                          max={100}
                          autoComplete="off"
                        />
                      </div>
                      <div style={{ paddingTop: "20px" }}>
                        <Text as="p" variant="bodyMd" tone="subdued">
                          {priority === 1
                            ? "Highest priority"
                            : priority <= 5
                              ? "High priority"
                              : priority <= 20
                                ? "Medium priority"
                                : "Low priority"}
                        </Text>
                      </div>
                    </InlineStack>
                  </BlockStack>
                </Card>

                {/* Display Position card */}
                <Card>
                  <BlockStack gap="400">
                    <BlockStack gap="200">
                      <Text as="h2" variant="headingMd" fontWeight="bold">
                        Widget Button Position
                      </Text>
                      <Text as="p" variant="bodyMd" tone="subdued">
                        Choose where the "Size Guide" button appears on your product pages.
                      </Text>
                    </BlockStack>
                    <BlockStack gap="300">
                      {(
                        [
                          { value: "floating" as const, label: "Floating button", desc: "A floating button appears near the size selector — highest visibility" },
                          { value: "above_desc" as const, label: "Above description", desc: "Shown above the product description section" },
                          { value: "below_desc" as const, label: "Below description", desc: "Shown below the product description section" },
                        ] satisfies { value: "floating" | "above_desc" | "below_desc"; label: string; desc: string }[]
                      ).map((opt) => (
                        <div
                          key={opt.value}
                          onClick={() => setButtonPosition(opt.value)}
                          style={{
                            cursor: "pointer",
                            borderRadius: "8px",
                            outline: buttonPosition === opt.value
                              ? "2px solid #005bd3"
                              : "1px solid #e1e3e5",
                            padding: "12px 16px",
                            background: buttonPosition === opt.value ? "#f0f5ff" : "#ffffff",
                            transition: "all 0.12s ease",
                          }}
                        >
                          <InlineStack gap="400" blockAlign="start">
                            <input
                              type="radio"
                              name="buttonPosition"
                              value={opt.value}
                              checked={buttonPosition === opt.value}
                              onChange={() => setButtonPosition(opt.value)}
                              style={{ flexShrink: 0, marginTop: "2px" }}
                            />
                            <BlockStack gap="100">
                              <Text as="p" variant="bodyMd">
                                {opt.label}
                              </Text>
                              <Text as="p" variant="bodyMd" tone="subdued">
                                {opt.desc}
                              </Text>
                            </BlockStack>
                          </InlineStack>
                        </div>
                      ))}
                    </BlockStack>
                  </BlockStack>
                </Card>

                {/* Country Targeting card */}
                <Card>
                  <BlockStack gap="400">
                    <BlockStack gap="200">
                      <Text as="h2" variant="headingMd" fontWeight="bold">
                        Country Targeting
                      </Text>
                      <Text as="p" variant="bodyMd" tone="subdued">
                        Limit this chart to customers in specific countries (e.g. show EU sizing only in Europe).
                      </Text>
                    </BlockStack>
                    <BlockStack gap="300">
                      {(
                        [
                          { value: "all" as const, label: "All countries", desc: "Show this chart to all visitors regardless of location" },
                          { value: "selected" as const, label: "Specific countries", desc: "Restrict to selected country codes (e.g. US, GB, DE)" },
                        ] satisfies { value: "all" | "selected"; label: string; desc: string }[]
                      ).map((opt) => (
                        <div
                          key={opt.value}
                          onClick={() => setCountries(opt.value)}
                          style={{
                            cursor: "pointer",
                            borderRadius: "8px",
                            outline: countries === opt.value
                              ? "2px solid #005bd3"
                              : "1px solid #e1e3e5",
                            padding: "12px 16px",
                            background: countries === opt.value ? "#f0f5ff" : "#ffffff",
                            transition: "all 0.12s ease",
                          }}
                        >
                          <InlineStack gap="400" blockAlign="start">
                            <input
                              type="radio"
                              name="countries"
                              value={opt.value}
                              checked={countries === opt.value}
                              onChange={() => setCountries(opt.value)}
                              style={{ flexShrink: 0, marginTop: "2px" }}
                            />
                            <BlockStack gap="100">
                              <Text as="p" variant="bodyMd">
                                {opt.label}
                              </Text>
                              <Text as="p" variant="bodyMd" tone="subdued">
                                {opt.desc}
                              </Text>
                            </BlockStack>
                          </InlineStack>
                        </div>
                      ))}
                    </BlockStack>
                    {countries === "selected" && (
                      <BlockStack gap="200">
                        <TextField
                          label="Country codes"
                          value={selectedCountries}
                          onChange={(value) => setSelectedCountries(value)}
                          placeholder="e.g. US, GB, DE, FR, CA"
                          autoComplete="off"
                        />
                        <Text as="p" variant="bodyMd" tone="subdued">
                          Comma-separated ISO 3166-1 alpha-2 codes. Leave blank to match all countries.
                        </Text>
                      </BlockStack>
                    )}
                  </BlockStack>
                </Card>
              </BlockStack>
            )}

            {/* ============================================================ */}
            {/* TAB: AI Recommendation                                        */}
            {/* ============================================================ */}
            {activeTab === "recommendation" && (
              <BlockStack gap="400">
                {/* Enable toggle card */}
                <Card>
                  <BlockStack gap="400">
                    <InlineStack gap="400" align="space-between" blockAlign="start">
                      <BlockStack gap="200">
                        <Text as="h2" variant="headingMd" fontWeight="bold">
                          AI Size Recommendation
                        </Text>
                        <Text as="p" variant="bodyMd" tone="subdued">
                          When enabled, customers can enter their height, weight, and body type to get a personalized size recommendation for this chart. Recommendations use your size data to predict the best fit.
                        </Text>
                      </BlockStack>
                      <Checkbox
                        label="Enable AI recommendation"
                        labelHidden
                        checked={recommendationEnabled}
                        onChange={(checked) => setRecommendationEnabled(checked)}
                      />
                    </InlineStack>
                    {recommendationEnabled && (
                      <Banner tone="success">
                        <Text as="p" variant="bodyMd">
                          Customers will see a "Find My Size" button on your product page. Make sure your chart has at least 3 size rows with chest and waist data for best accuracy.
                        </Text>
                      </Banner>
                    )}
                  </BlockStack>
                </Card>

                {/* How it works card */}
                <Card>
                  <BlockStack gap="400">
                    <Text as="h2" variant="headingMd" fontWeight="bold">
                      How AI Recommendations Work
                    </Text>
                    <BlockStack gap="400">
                      {[
                        { step: "1", title: "Customer enters measurements", desc: "Height, weight, and body type are collected via a short form shown next to your size chart." },
                        { step: "2", title: "AI matches to your size data", desc: "Our algorithm cross-references the inputs with your chart rows to find the closest fit, weighted by body type." },
                        { step: "3", title: "Personalized recommendation shown", desc: "The recommended size is highlighted in the chart with a confidence indicator (high/medium/low)." },
                      ].map((item) => (
                        <InlineStack key={item.step} gap="400" blockAlign="start">
                          <div
                            style={{
                              width: "28px",
                              height: "28px",
                              borderRadius: "50%",
                              background: "#2c6ecb",
                              color: "#fff",
                              display: "flex",
                              alignItems: "center",
                              justifyContent: "center",
                              fontSize: "13px",
                              fontWeight: 700,
                              flexShrink: 0,
                            }}
                          >
                            {item.step}
                          </div>
                          <BlockStack gap="100">
                            <Text as="p" variant="bodyMd">
                              {item.title}
                            </Text>
                            <Text as="p" variant="bodyMd" tone="subdued">
                              {item.desc}
                            </Text>
                          </BlockStack>
                        </InlineStack>
                      ))}
                    </BlockStack>
                  </BlockStack>
                </Card>

                {/* Requirements card */}
                <Card>
                  <BlockStack gap="400">
                    <Text as="h2" variant="headingMd" fontWeight="bold">
                      Requirements for Best Accuracy
                    </Text>
                    <List>
                      <List.Item>At least 3 size rows (S, M, L or numeric sizes)</List.Item>
                      <List.Item>Chest and/or waist measurements in your chart columns</List.Item>
                      <List.Item>AI Recommender enabled in Recommender settings</List.Item>
                      <List.Item>Starter plan or above</List.Item>
                    </List>
                    <Button url="/app/recommender">Configure Recommender Settings</Button>
                  </BlockStack>
                </Card>
              </BlockStack>
            )}

            {/* ============================================================ */}
            {/* TAB: Settings                                                 */}
            {/* ============================================================ */}
            {activeTab === "settings" && (
              <BlockStack gap="400">
                {/* How to Measure card */}
                <Card>
                  <BlockStack gap="400">
                    <BlockStack gap="200">
                      <Text as="h2" variant="headingMd" fontWeight="bold">
                        How to Measure
                      </Text>
                      <Text as="p" variant="bodyMd" tone="subdued">
                        This guide is shown alongside your size chart to help customers measure correctly.
                      </Text>
                    </BlockStack>
                    <Card>
                      <BlockStack gap="400">
                        <Text as="p" variant="bodyMd">
                          Measurement Instructions
                        </Text>
                        <List>
                          <List.Item>
                            <strong>Chest:</strong> Measure around the fullest part of your chest, keeping the tape parallel to the floor.
                          </List.Item>
                          <List.Item>
                            <strong>Waist:</strong> Measure around the narrowest part of your waist, typically 1 inch above the navel.
                          </List.Item>
                          <List.Item>
                            <strong>Hips:</strong> Measure around the fullest part of your hips, approximately 8 inches below the waist.
                          </List.Item>
                          <List.Item>
                            <strong>Inseam:</strong> Measure from the crotch seam down to the ankle bone along the inside of the leg.
                          </List.Item>
                        </List>
                        <Text as="p" variant="bodyMd" tone="subdued">
                          Tip: Use a soft measuring tape and measure directly on the skin or over light clothing for the most accurate fit.
                        </Text>
                      </BlockStack>
                    </Card>
                  </BlockStack>
                </Card>

                {/* Danger Zone */}
                {!isNew && (
                  <Banner tone="critical" title="Danger Zone">
                    <BlockStack gap="400">
                      <Text as="p" variant="bodyMd">
                        Permanently deletes this chart and all its product assignments. This action cannot be undone.
                      </Text>
                      <assignmentFetcher.Form method="post">
                        <input type="hidden" name="intent" value="delete" />
                        <Button submit tone="critical" variant="primary">
                          Delete Chart Permanently
                        </Button>
                      </assignmentFetcher.Form>
                    </BlockStack>
                  </Banner>
                )}
              </BlockStack>
            )}
          </BlockStack>
        </Layout.Section>

        {/* ================================================================ */}
        {/* CHART INFO BAR (compact, inline for saved charts)                */}
        {/* ================================================================ */}
        {!isNew && chart && (
          <Layout.Section>
            <Card>
              <InlineStack gap="600" wrap>
                {[
                  { label: "Created", value: formatDate(chart.createdAt) },
                  { label: "Updated", value: formatDate(chart.updatedAt) },
                  { label: "Assignments", value: String(assignments.length) },
                  { label: "Rows", value: String(chartData.rows.length) },
                  { label: "Columns", value: String(chartData.headers.length) },
                ].map((item) => (
                  <BlockStack key={item.label} gap="100">
                    <Text as="p" variant="bodySm" tone="subdued">
                      {item.label}
                    </Text>
                    <Text as="p" variant="bodyMd">
                      {item.value}
                    </Text>
                  </BlockStack>
                ))}
              </InlineStack>
            </Card>
          </Layout.Section>
        )}
      </Layout>
    </Page>
  );
}

content.content:
1:import { useEffect, useRef, useState } from "react";
2:import type { LoaderFunctionArgs, ActionFunctionArgs } from "react-router";
3:import { useLoaderData, useFetcher, redirect, useNavigate } from "react-router";
4:import { useAppBridge } from "@shopify/app-bridge-react";
5:import { authenticate } from "../shopify.server";
6:import db from "../db.server";
7:import {
